until runs=$(gh run list --branch ike/round-beats --limit 4 --json status,conclusion,workflowName,headSha --jq "[.[] | select(.headSha | startswith(\"ff4d4f6\"))]" 2>/dev/null); [ -n "$runs" ] && [ "$runs" != "[]" ] && ! echo "$runs" | grep -q "in_progress\|queued\|pending"; do sleep 45; done; echo "$runs"
